import{_ as e,o as d,c as o,a3 as a}from"./chunks/framework.B5WAEDB7.js";const p=JSON.parse('{"title":"配置参考","description":"","frontmatter":{},"headers":[],"relativePath":"configuration.md","filePath":"configuration.md","lastUpdated":1786258579000}'),c={name:"configuration.md"};function r(n,t,i,s,l,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="配置参考" tabindex="-1">配置参考 <a class="header-anchor" href="#配置参考" aria-label="Permalink to &quot;配置参考&quot;">​</a></h1><p><code>appsettings</code> 的全量配置节说明。所有键名与默认值对照仓库里的 <code>appsettings.Development.json</code> 与各 Options 类核实。</p><h2 id="文件与优先级" tabindex="-1">文件与优先级 <a class="header-anchor" href="#文件与优先级" aria-label="Permalink to &quot;文件与优先级&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>backend/src/main/XiHan.BasicApp.WebHost/</span></span>\n<span class="line"><span>├── appsettings.json                 # 基础（Logging / AllowedHosts / CodeGeneration）</span></span>\n<span class="line"><span>├── appsettings.Development.json     # 开发环境（完整示例，带逐项注释）</span></span>\n<span class="line"><span>└── appsettings.Production.json      # 生产环境</span></span></code></pre></div><p>优先级（后者覆盖前者）：<code>appsettings.json</code> → <code>appsettings.{Environment}.json</code> → 环境变量 → 命令行。</p><div class="tip custom-block"><p class="custom-block-title">环境变量写法</p><p>配置层级用<strong>双下划线</strong>表示：<code>XiHan:Authentication:Jwt:SecretKey</code> → <code>XiHan__Authentication__Jwt__SecretKey</code>。</p><p><strong>生产的密钥类配置一律走环境变量或密钥库，不要提交明文。</strong> 生产 <code>appsettings</code> 通常被 gitignore，需要在服务器上单独维护——这也是几个开关（如 <code>EnableDiffLog</code>）最容易漏配的原因。</p></div><h2 id="hosting" tabindex="-1"><code>Hosting</code> <a class="header-anchor" href="#hosting" aria-label="Permalink to &quot;`Hosting`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>Urls</code></td><td>监听地址与端口，多个用分号分隔</td><td><code>http://127.0.0.1:9708</code></td></tr></tbody></table><p>仓库 Development 与 Production 当前都监听 <code>9708</code>；Docker Compose 也在容器内使用 <code>9708</code>，宿主机端口可由 <code>BACKEND_PORT</code> 覆盖。开发环境改端口后要同步修改前端的 <code>VITE_DEV_PROXY_TARGET</code>。</p><h2 id="xihan-observability" tabindex="-1"><code>XiHan:Observability</code> <a class="header-anchor" href="#xihan-observability" aria-label="Permalink to &quot;`XiHan:Observability`&quot;">​</a></h2><p>链路追踪（OpenTelemetry）。</p><table tabindex="0"><thead><tr><th>键</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>Enabled</code></td><td><code>false</code></td><td><strong>总开关</strong>。开启后每请求产生 W3C Activity，TraceId 变 32-hex，日志/审计/事件总线统一同源；关则退回 Kestrel <code>TraceIdentifier</code></td></tr><tr><td><code>ServiceName</code></td><td>—</td><td>写入 OTel Resource 的 <code>service.name</code></td></tr><tr><td><code>SamplingRatio</code></td><td>—</td><td>采样率 0~1，开发可设 <code>1.0</code> 全采</td></tr><tr><td><code>ConsoleExporter</code></td><td><code>false</code></td><td>控制台打印 span（调试用）</td></tr><tr><td><code>OtlpEndpoint</code></td><td><code>&quot;&quot;</code></td><td>OTLP 导出端点（如 <code>http://localhost:4317</code>）。为空则只在本地产生 TraceId，不外发到 Jaeger/Tempo</td></tr></tbody></table><h2 id="xihan-distributedids-snowflakeid" tabindex="-1"><code>XiHan:DistributedIds:SnowflakeId</code> <a class="header-anchor" href="#xihan-distributedids-snowflakeid" aria-label="Permalink to &quot;`XiHan:DistributedIds:SnowflakeId`&quot;">​</a></h2><p>雪花 ID 生成器。</p><table tabindex="0"><thead><tr><th>键</th><th>说明</th></tr></thead><tbody><tr><td><code>WorkerId</code></td><td><strong>同一集群内每个节点必须唯一</strong>，否则生成重复 ID。多节点部署务必逐节点改</td></tr><tr><td><code>DataCenterId</code></td><td>多机房区分，单机房固定即可</td></tr><tr><td><code>BaseTime</code></td><td>起始纪元，<strong>一经上线不可更改</strong>（改动会导致 ID 回退甚至冲突）</td></tr><tr><td><code>WorkerIdBitLength</code></td><td>机器码位长，与序列号位长之和不超过 22。6 位 → WorkerId 上限 0-63</td></tr><tr><td><code>SeqBitLength</code></td><td>序列号位长，决定同毫秒并发上限，<strong>一经上线不可更改</strong></td></tr><tr><td><code>SnowflakeIdType</code></td><td><code>SnowFlakeMethod</code>（漂移算法，抗时钟回拨、吞吐更高）/ <code>ClassicSnowFlakeMethod</code></td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">多节点必改 WorkerId</p><p>这是最容易忽略、后果最严重的一项：两个节点同 <code>WorkerId</code> 会生成重复主键，且不会立刻报错，等到唯一约束冲突时数据已经乱了。</p></div><h2 id="xihan-authentication" tabindex="-1"><code>XiHan:Authentication</code> <a class="header-anchor" href="#xihan-authentication" aria-label="Permalink to &quot;`XiHan:Authentication`&quot;">​</a></h2><h3 id="passwordhasher-pbkdf2" tabindex="-1"><code>PasswordHasher</code>（PBKDF2） <a class="header-anchor" href="#passwordhasher-pbkdf2" aria-label="Permalink to &quot;`PasswordHasher`（PBKDF2）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>键</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>Version</code></td><td><code>1</code></td><td>哈希方案版本，用于将来平滑升级算法（老密码按旧版本校验）</td></tr><tr><td><code>Iterations</code></td><td><code>600000</code></td><td>迭代次数，OWASP 对 PBKDF2-SHA256 的推荐量级</td></tr><tr><td><code>SaltSize</code> / <code>HashSize</code></td><td><code>32</code> / <code>32</code></td><td>盐与输出长度（字节）</td></tr><tr><td><code>HashAlgorithm</code></td><td><code>SHA256</code></td><td>—</td></tr></tbody></table><h3 id="jwt" tabindex="-1"><code>Jwt</code> <a class="header-anchor" href="#jwt" aria-label="Permalink to &quot;`Jwt`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>键</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>SecretKey</code></td><td>—</td><td><strong>签名密钥，生产务必改为高强度随机值并保密</strong>（走环境变量/密钥库）</td></tr><tr><td><code>Issuer</code> / <code>Audience</code></td><td>—</td><td>签发者 / 受众</td></tr><tr><td><code>AccessTokenExpirationMinutes</code></td><td><code>60</code>（框架默认）</td><td>访问令牌有效期</td></tr><tr><td><code>RefreshTokenExpirationDays</code></td><td><code>7</code></td><td>刷新令牌有效期</td></tr><tr><td><code>ClockSkewMinutes</code></td><td><code>5</code></td><td>允许的时钟偏差，容忍多节点时间误差</td></tr></tbody></table><blockquote><p>仓库的 Development 配置把 <code>AccessTokenExpirationMinutes</code> 设为 <code>120</code>，以实际配置为准。</p></blockquote><h3 id="oauth-第三方登录" tabindex="-1"><code>OAuth</code>（第三方登录） <a class="header-anchor" href="#oauth-第三方登录" aria-label="Permalink to &quot;`OAuth`（第三方登录）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>键</th><th>说明</th></tr></thead><tbody><tr><td><code>Enabled</code></td><td>总开关</td></tr><tr><td><code>FrontendCallbackUrl</code></td><td>登录成功后跳回的前端回调页</td></tr><tr><td><code>Providers[]</code></td><td>各提供商：<code>Name</code>（<strong>内部标识，勿改</strong>）、<code>DisplayName</code>、<code>Enabled</code>、<code>ClientId</code>、<code>ClientSecret</code>、<code>Scopes[]</code></td></tr></tbody></table><p>内建 github / gitee / google / qq，需到对应平台申请后替换 <code>ClientId</code> / <code>ClientSecret</code>。</p><h2 id="xihan-data-sqlsugarcore" tabindex="-1"><code>XiHan:Data:SqlSugarCore</code> <a class="header-anchor" href="#xihan-data-sqlsugarcore" aria-label="Permalink to &quot;`XiHan:Data:SqlSugarCore`&quot;">​</a></h2><h3 id="连接" tabindex="-1">连接 <a class="header-anchor" href="#连接" aria-label="Permalink to &quot;连接&quot;">​</a></h3><p><code>ConnectionConfigs[]</code> 每项：</p><table tabindex="0"><thead><tr><th>键</th><th>说明</th></tr></thead><tbody><tr><td><code>ConfigId</code></td><td>连接唯一标识（多库/多租户路由用），字符串</td></tr><tr><td><code>ConnectionString</code></td><td>主库连接串</td></tr><tr><td><code>DbType</code></td><td><code>PostgreSQL</code> / <code>MySql</code> / <code>SqlServer</code> / <code>Oracle</code> / <code>Dm</code> / <code>Kdbndp</code> 等</td></tr><tr><td><code>IsAutoCloseConnection</code></td><td>是否自动关闭连接</td></tr><tr><td><code>SlaveConnectionConfigs[]</code></td><td>从库（读写分离）；空数组=单库</td></tr></tbody></table><p>配了从库后 SELECT 自动走从库、写与事务走主库，业务无感知。</p><div class="warning custom-block"><p class="custom-block-title"><code>HitRate</code> 配不上</p><p><code>HitRate</code>（读权重）是 SqlSugar 的<strong>字段</strong>、绑不上 <code>appsettings</code>，写了也无效、恒为 0。框架会把权重为 0 的从库归一化为 <code>DefaultSlaveHitRate</code>（默认 10），所以不写也能等权分担读。</p><p>需要差异化权重、挂 <code>ConfigureExternalServices</code> 或自写探活，用代码钩子 <code>XiHanSqlSugarCoreOptions.ConfigureConnectionConfigs</code>。</p></div><h3 id="日志与诊断" tabindex="-1">日志与诊断 <a class="header-anchor" href="#日志与诊断" aria-label="Permalink to &quot;日志与诊断&quot;">​</a></h3><table tabindex="0"><thead><tr><th>键</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>EnableSqlLog</code></td><td><code>false</code></td><td>打印所有 SQL（<strong>生产建议关闭</strong>，日志会爆量）</td></tr><tr><td><code>EnableSqlErrorLog</code></td><td><code>true</code></td><td>记录 SQL 异常</td></tr><tr><td><code>EnableSlowSqlLog</code></td><td><code>true</code></td><td>记录慢 SQL</td></tr><tr><td><code>SlowSqlThresholdMilliseconds</code></td><td>—</td><td>慢 SQL 阈值，纯观测用途、不影响语句执行</td></tr><tr><td><code>CommandTimeoutSeconds</code></td><td><code>300</code></td><td>ADO 命令超时，0/负值不覆盖；<strong>须明显大于慢 SQL 阈值</strong></td></tr></tbody></table><h3 id="初始化" tabindex="-1">初始化 <a class="header-anchor" href="#初始化" aria-label="Permalink to &quot;初始化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>键</th><th>说明</th></tr></thead><tbody><tr><td><code>EnableDbInitialization</code></td><td>启动时自动建库（库不存在则创建）</td></tr><tr><td><code>EnableTableInitialization</code></td><td>启动时 CodeFirst 建表</td></tr><tr><td><code>EnableDataSeeding</code></td><td>启动时写入种子数据</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">建表只建不改</p><p><code>DbInitializer</code> <strong>表存在就跳过、从不为已有表补列</strong>。给既有实体加字段后，存量库必须通过前向 <code>UpdateScripts</code>（或部署流程中的等价迁移步骤）执行 <code>ALTER TABLE</code>。当前 BasicApp 不会自动触发升级引擎，见<a href="./backend/upgrade">升级与迁移</a>。</p></div><h3 id="enabledifflog" tabindex="-1"><code>EnableDiffLog</code> <a class="header-anchor" href="#enabledifflog" aria-label="Permalink to &quot;`EnableDiffLog`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>键</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>EnableDiffLog</code></td><td><strong><code>false</code></strong></td><td>实体差异日志（<code>SysDiffLog</code>）<strong>总开关</strong></td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">数据变更日志页恒空的头号原因</p><p>默认是 <code>false</code>——不开则 Diff AOP 根本不挂载，收集到的差异被直接丢弃。生产 <code>appsettings</code> 常被 gitignore，最容易漏配的就是这一项。</p><p>代价：开启后 update/delete 会先查一次旧值算差异，<strong>每个写操作多一次 SELECT</strong>。且只覆盖走仓储的写，绕过仓储直接用 DbClient 的写（如 <code>UpdateColumns</code>）不产生差异日志。</p></div><h3 id="从库健康探针" tabindex="-1">从库健康探针 <a class="header-anchor" href="#从库健康探针" aria-label="Permalink to &quot;从库健康探针&quot;">​</a></h3><table tabindex="0"><thead><tr><th>键</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>DefaultSlaveHitRate</code></td><td><code>10</code></td><td>从库权重归一化默认值</td></tr><tr><td><code>EnableSlaveHealthCheck</code></td><td><code>false</code></td><td>周期探活，不可用从库自动摘除读权重</td></tr><tr><td><code>SlaveHealthCheckIntervalSeconds</code></td><td><code>30</code></td><td>探测周期</td></tr><tr><td><code>SlaveFailureCooldownSeconds</code></td><td><code>120</code></td><td>故障冷却窗口，恢复后先冷却再回填权重避免抖动</td></tr></tbody></table><h2 id="xihan-caching-redis" tabindex="-1"><code>XiHan:Caching:Redis</code> <a class="header-anchor" href="#xihan-caching-redis" aria-label="Permalink to &quot;`XiHan:Caching:Redis`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>IsEnabled</code></td><td>—</td><td><strong>关闭则退化为进程内内存缓存</strong>（失去分布式缓存/锁/队列）</td></tr><tr><td><code>Configuration</code></td><td>—</td><td>连接串 <code>host:port,user=,password=,defaultDatabase=</code></td></tr><tr><td><code>InstanceName</code></td><td><code>XiHan:</code></td><td>缓存 Key 统一前缀（隔离不同应用/环境）</td></tr><tr><td><code>ConnectTimeout</code> / <code>SyncTimeout</code> / <code>AsyncTimeout</code></td><td><code>5000</code></td><td>各类超时（毫秒）</td></tr><tr><td><code>AllowAdmin</code></td><td><code>false</code></td><td>允许管理类命令（FLUSHDB/CONFIG），<strong>生产慎开</strong></td></tr><tr><td><code>UseSsl</code></td><td><code>false</code></td><td>—</td></tr><tr><td><code>AbortOnConnectFail</code></td><td><code>false</code></td><td><code>false</code> = 后台持续重连，更适合生产</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">关掉 Redis 的连锁反应</p><p><code>IsEnabled=false</code> 时分布式锁退化为进程内锁——<strong>多实例部署会各跑各的</strong>：定时任务重复执行、后台 Worker 不再单活、工作流定时器多实例并发。单机开发无所谓，生产必须开。</p></div><h2 id="xihan-web" tabindex="-1"><code>XiHan:Web</code> <a class="header-anchor" href="#xihan-web" aria-label="Permalink to &quot;`XiHan:Web`&quot;">​</a></h2><h3 id="core-clientinfo" tabindex="-1"><code>Core:ClientInfo</code> <a class="header-anchor" href="#core-clientinfo" aria-label="Permalink to &quot;`Core:ClientInfo`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>键</th><th>说明</th></tr></thead><tbody><tr><td><code>EnableIpRegion</code></td><td>是否启用 IP 归属地解析</td></tr><tr><td><code>Ip2RegionDbPath</code></td><td>ip2region 离线库路径</td></tr></tbody></table><h3 id="api-auth" tabindex="-1"><code>Api:Auth</code> <a class="header-anchor" href="#api-auth" aria-label="Permalink to &quot;`Api:Auth`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>键</th><th>说明</th></tr></thead><tbody><tr><td><code>RequireAuthenticatedUser</code></td><td>全局要求已认证（匿名接口需 <code>[AllowAnonymous]</code> 显式放行）</td></tr><tr><td><code>SignalRHubPathPrefix</code></td><td>SignalR Hub 路由前缀，默认 <code>/hubs</code></td></tr></tbody></table><h3 id="api-cors" tabindex="-1"><code>Api:Cors</code> <a class="header-anchor" href="#api-cors" aria-label="Permalink to &quot;`Api:Cors`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>键</th><th>说明</th></tr></thead><tbody><tr><td><code>AllowedOrigins[]</code></td><td>允许的来源。<strong>携带凭证时不能用 <code>*</code>，必须显式列出</strong></td></tr><tr><td><code>AllowAnyOrigin</code></td><td>与 <code>AllowCredentials</code> <strong>互斥</strong></td></tr><tr><td><code>AllowAnyMethod</code> / <code>AllowAnyHeader</code></td><td>—</td></tr><tr><td><code>AllowCredentials</code></td><td>是否允许携带 Cookie/Authorization</td></tr><tr><td><code>ExposedHeaders[]</code></td><td>额外暴露给前端 JS 读取的响应头</td></tr><tr><td><code>PreflightMaxAgeSeconds</code></td><td>预检结果缓存秒数</td></tr></tbody></table><h3 id="api-openapisecurity" tabindex="-1"><code>Api:OpenApiSecurity</code> <a class="header-anchor" href="#api-openapisecurity" aria-label="Permalink to &quot;`Api:OpenApiSecurity`&quot;">​</a></h3><p>开放接口签名/防重放/加密，完整说明见 <a href="./api-guide#开放接口-签名调用-无-jwt">接口对接指南</a>。</p><table tabindex="0"><thead><tr><th>键</th><th>框架默认</th><th>说明</th></tr></thead><tbody><tr><td><code>IsEnabled</code></td><td><code>false</code></td><td>总开关</td></tr><tr><td><strong><code>ProtectedPathPrefixes</code></strong></td><td><strong><code>[&quot;/api&quot;]</code></strong></td><td><strong>必须覆盖</strong>，否则开启后整站接口都要验签。BasicApp 配 <code>[&quot;/api/openapi&quot;]</code></td></tr><tr><td><code>IgnoredPathPrefixes</code></td><td>—</td><td>豁免前缀（文档/健康检查等）</td></tr><tr><td><code>AllowUnsignedRequests</code></td><td><code>false</code></td><td>灰度开关：允许未带安全头的请求放行</td></tr><tr><td><code>RequireContentSignature</code></td><td><code>true</code></td><td>强制校验内容签名</td></tr><tr><td><code>EnableReplayProtection</code></td><td><code>true</code></td><td>防重放（Nonce 去重）</td></tr><tr><td><code>TimestampToleranceSeconds</code> / <code>NonceExpireSeconds</code></td><td><code>300</code></td><td>时间戳容差 / Nonce 存活期</td></tr><tr><td><code>MaxRequestBodySize</code></td><td>2 MiB</td><td>最大请求体</td></tr><tr><td><code>EnableResponseEncryption</code></td><td><code>true</code></td><td>启用响应加密</td></tr><tr><td><code>DefaultSignatureAlgorithm</code></td><td><code>HMACSHA256</code></td><td>也支持 <code>HMACSHA512</code> / <code>RSASHA256</code> / <code>SM2</code></td></tr><tr><td><code>DefaultContentSignatureAlgorithm</code></td><td><code>SHA256</code></td><td>也支持 <code>SHA512</code></td></tr><tr><td><code>Clients[]</code></td><td>—</td><td>配置文件里的静态客户端（<code>AccessKey</code> / <code>SecretKey</code> / <code>EncryptKey</code> / <code>IpWhitelist</code> 等）。<strong>密钥敏感，生产走环境变量</strong></td></tr></tbody></table><h3 id="realtime-signalr" tabindex="-1"><code>RealTime:SignalR</code> <a class="header-anchor" href="#realtime-signalr" aria-label="Permalink to &quot;`RealTime:SignalR`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>键</th><th>说明</th></tr></thead><tbody><tr><td><code>EnableDetailedErrors</code></td><td>详细错误（<strong>生产设 <code>false</code></strong>）</td></tr><tr><td><code>KeepAliveInterval</code> / <code>ClientTimeoutInterval</code> / <code>HandshakeTimeout</code></td><td>心跳与超时（<code>hh:mm:ss</code>）</td></tr><tr><td><code>MaximumReceiveMessageSize</code></td><td>最大接收消息大小（字节）</td></tr><tr><td><code>StreamBufferCapacity</code></td><td>流缓冲容量</td></tr><tr><td><code>MaximumParallelInvocationsPerClient</code></td><td>每客户端最大并行调用数</td></tr><tr><td><code>EnableConnectionMetrics</code></td><td>连接指标</td></tr></tbody></table><h3 id="gateway-grayrouting" tabindex="-1"><code>Gateway</code> / <code>GrayRouting</code> <a class="header-anchor" href="#gateway-grayrouting" aria-label="Permalink to &quot;`Gateway` / `GrayRouting`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>键</th><th>说明</th></tr></thead><tbody><tr><td><code>Gateway.EnableGrayRouting</code> / <code>EnableRequestTracing</code> / <code>EnableRateLimiting</code> / <code>EnableCircuitBreaker</code></td><td>各能力开关</td></tr><tr><td><code>Gateway.RequestTimeoutSeconds</code></td><td>网关请求超时</td></tr><tr><td><code>Gateway.AllowedOrigins[]</code> / <code>GlobalHeaders</code></td><td>允许来源 / 统一注入的响应头</td></tr><tr><td><code>GrayRouting.Rules[]</code></td><td>灰度规则：<code>RuleType</code>（<strong>1=按百分比 2=用户白名单 3=租户 4=请求头</strong>）、<code>Priority</code>（<strong>越大越优先</strong>）、<code>TargetVersion</code>、<code>Configuration</code>（JSON 字符串参数）、<code>IsEnabled</code></td></tr></tbody></table><h2 id="xihan-upgrade" tabindex="-1"><code>XiHan:Upgrade</code> <a class="header-anchor" href="#xihan-upgrade" aria-label="Permalink to &quot;`XiHan:Upgrade`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>说明</th></tr></thead><tbody><tr><td><code>MinSupportVersion</code> / <code>AppVersion</code></td><td>最低来源版本 / 当前版本（留空则运行时探测程序集版本）</td></tr><tr><td><code>MigrationsRootPath</code></td><td>迁移脚本根目录</td></tr><tr><td><code>LockResourceKey</code> / <code>LockExpirySeconds</code></td><td>分布式锁（防多节点并发升级）</td></tr><tr><td><code>EnableAutoCheckOnStartup</code></td><td>启动后初始化/检查版本状态；当前 BasicApp 未调用升级执行入口，不会因此自动跑 SQL</td></tr><tr><td><code>NodeName</code> / <code>PrimaryNodeName</code></td><td>当前节点 / <strong>仅主节点执行迁移，其余等待</strong></td></tr><tr><td><code>EnableMultiTenantIsolation</code></td><td>是否按租户逐库执行</td></tr><tr><td><code>ConnectionConfigId</code></td><td>升级使用的连接</td></tr><tr><td><code>EnableMaintenanceMode</code></td><td>升级期间进入维护模式</td></tr><tr><td><code>EnableFileUpdate</code> / <code>EnableRollingRestart</code></td><td>文件更新 / 滚动重启</td></tr></tbody></table><p>版本状态与执行历史分别保存在 <code>SysVersion</code>、<code>SysMigrationHistory</code>，不使用 <code>version.txt</code>。引擎被显式调用后会按 <code>UpdateScripts/{version}.sql</code> 顺序处理平台库及配置为独立库的租户，锁租约避免多节点并发。当前 BasicApp 没有 <code>IUpgradeCoordinator</code> / <code>IUpgradeEngine</code> 调用入口，因此启动只初始化版本状态、不执行脚本；完整边界见<a href="./backend/upgrade">升级与迁移</a>。当前仓库脚本使用 PostgreSQL SQL，切换数据库提供程序时需要维护对应方言的脚本。</p><h2 id="xihan-localization" tabindex="-1"><code>XiHan:Localization</code> <a class="header-anchor" href="#xihan-localization" aria-label="Permalink to &quot;`XiHan:Localization`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>说明</th></tr></thead><tbody><tr><td><code>ResourcesPath</code></td><td>资源文件目录</td></tr><tr><td><code>DefaultResourceName</code></td><td>默认资源名</td></tr><tr><td><code>DefaultCulture</code></td><td>默认文化，如 <code>zh-CN</code></td></tr><tr><td><code>EnumResourceName</code></td><td><strong>枚举文案资源名</strong>（枚举标签的单一事实源，如 <code>Enums</code>）</td></tr><tr><td><code>EnableDynamicJsonReload</code></td><td>资源 JSON 热重载</td></tr></tbody></table><h2 id="xihan-objectstorage" tabindex="-1"><code>XiHan:ObjectStorage</code> <a class="header-anchor" href="#xihan-objectstorage" aria-label="Permalink to &quot;`XiHan:ObjectStorage`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>Local.RootPath</code></td><td><code>wwwroot/uploads</code></td><td>文件落盘根目录；这是 BasicApp 的显式配置，不是 Framework 3.10.1 的 <code>LocalStorageOptions</code> 默认值</td></tr><tr><td><code>Local.UrlPrefix</code></td><td><code>/uploads</code></td><td>对外访问 URL 前缀（<strong>根相对路径</strong>，跨源时前端拼 API origin）</td></tr></tbody></table><p>对象存储的其余后端（S3/OSS/COS/MinIO）<strong>配置落库</strong>在 <code>SysStorageConfig</code>，不写 <code>appsettings</code>。见 <a href="./backend/file#存储配置-file-storage">文件与存储</a>。</p><h2 id="xihan-virtualfilesystem" tabindex="-1"><code>XiHan:VirtualFileSystem</code> <a class="header-anchor" href="#xihan-virtualfilesystem" aria-label="Permalink to &quot;`XiHan:VirtualFileSystem`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>说明</th></tr></thead><tbody><tr><td><code>IncludeCurrentDirectory</code> / <code>IncludeAppBaseDirectory</code></td><td>是否挂载当前工作目录 / 应用基目录</td></tr></tbody></table><h2 id="xihan-workflow" tabindex="-1"><code>XiHan:Workflow</code> <a class="header-anchor" href="#xihan-workflow" aria-label="Permalink to &quot;`XiHan:Workflow`&quot;">​</a></h2><p>工作流引擎，见 <a href="https://framework.docs.xihanfun.com/packages/workflow#%E9%85%8D%E7%BD%AE" target="_blank" rel="noreferrer">框架 · Workflow</a>。要点：<code>MaxNodeExecutionsPerBurst</code>（默认 1000）、<code>MaxSubWorkflowDepth</code>（默认 16）、<code>Worker:IsTimerEnabled</code>（<strong>关掉后延时/重试/超时书签不会被自动恢复</strong>）。</p><h2 id="saas-seed" tabindex="-1"><code>Saas:Seed</code> <a class="header-anchor" href="#saas-seed" aria-label="Permalink to &quot;`Saas:Seed`&quot;">​</a></h2><p>注意这一节<strong>不在 <code>XiHan:</code> 命名空间下</strong>。</p><table tabindex="0"><thead><tr><th>键</th><th>说明</th></tr></thead><tbody><tr><td><code>EnableDemoData</code></td><td>演示种子开关，<strong>缺省或非法值都视为启用</strong>，显式 <code>false</code> 才整体跳过</td></tr><tr><td><code>SuperAdminPassword</code></td><td>超管初始密码（环境变量 <code>Saas__Seed__SuperAdminPassword</code>）。<strong>生产务必覆盖</strong></td></tr></tbody></table><h2 id="codegeneration" tabindex="-1"><code>CodeGeneration</code> <a class="header-anchor" href="#codegeneration" aria-label="Permalink to &quot;`CodeGeneration`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>键</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>EnableCustomPathDisk</code></td><td><code>false</code></td><td>是否允许生成到自定义磁盘路径</td></tr><tr><td><code>AllowedRootPaths[]</code></td><td><code>[]</code></td><td>允许写入的根路径白名单</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">生产不要开 <code>EnableCustomPathDisk</code></p><p>开启后代码生成器可以往服务器磁盘写文件，<code>AllowedRootPaths</code> 是唯一的边界。生产环境保持关闭，用 Zip 下载。</p></div><h2 id="数据库里的配置" tabindex="-1">数据库里的配置 <a class="header-anchor" href="#数据库里的配置" aria-label="Permalink to &quot;数据库里的配置&quot;">​</a></h2><p>有几类配置<strong>刻意不放 <code>appsettings</code></strong>，而是落库以便按租户隔离与运行期热切换：</p><table tabindex="0"><thead><tr><th>内容</th><th>表</th><th>页面</th></tr></thead><tbody><tr><td>业务参数与功能开关</td><td><code>SysConfig</code></td><td><code>/setting/config</code></td></tr><tr><td>存储后端</td><td><code>SysStorageConfig</code></td><td><code>/file/storage</code></td></tr><tr><td>邮件 / 短信网关</td><td><code>SysEmailConfig</code> / <code>SysSmsConfig</code></td><td><code>/setting/email-config</code>、<code>/setting/sms-config</code></td></tr><tr><td>机器人</td><td><code>SysBotConfig</code> / <code>SysTelegramBot</code></td><td><code>/setting/bot-config</code>、<code>/setting/telegram-bot</code></td></tr><tr><td>AI Provider / 提示词</td><td><code>SysAiProvider</code> / <code>SysAiPrompt</code></td><td><code>/develop/ai-provider</code>、<code>/develop/ai-prompt</code></td></tr></tbody></table><p>它们通过 <code>services.Replace(...)</code> 覆盖框架默认的配置源实现。判断标准见 <a href="./backend/settings#参数配置-setting-config">系统设置</a>。</p><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./dev-environment">开发环境</a>：Docker 起依赖并对齐连接串</li><li><a href="./deployment">部署</a>：生产部署与环境变量注入</li><li><a href="./faq">常见问题</a>：配置类故障速查</li><li><a href="./backend/settings">系统设置</a>：落库配置的管理页面</li></ul>',82)])])}const g=e(c,[["render",r]]);export{p as __pageData,g as default};
